const int N = 2008;

struct Tour {
    int to;
    int hour;
    int duration;
    bool used;
};

int n, totalUsed;
vector<vector<Tour>> graph(N);
bool vis[N];

bool reachDFS(int v, int target);
bool reachablePast(int v, Tour &t);
int endTime(Tour &t, int now);
int dfs(int v, int now);
void tc(int tci);
int main();

bool reachDFS(int v, int target) {
    vis[v] = true;
    if (v == target) return true;

    for (Tour &t : graph[v]) {
        if (!vis[t.to] && reachDFS(t.to, target)) return true;
    }

    return false;
}

bool reachablePast(int v, Tour &t) {
    vis[v] = true;
    if (v == t.to) return true;

    for (Tour &tt : graph[v]) {
        if (!tt.used && !vis[tt.to] && reachablePast(tt.to, t)) return true;
    }

    return false;
}

int endTime(Tour &t, int now) {
    int end_time = now + t.duration;
    if (end_time < t.hour) return t.hour;
    return end_time;
}

int dfs(int v, int now) {
    int res = 0;

    for (Tour &t : graph[v]) {
        if (!t.used) {
            if (!reachablePast(v, t)) {
                t.used = true;
                totalUsed++;
                res = max(res, endTime(t, now) - t.hour);
                res += dfs(t.to, endTime(t, now));
            }
        }
    }

    return res;
}

