using namespace std;

int H, W, M;
int he[12][12];
int wa[12][12];

bool inrange(int y, int x);
int accwa(int y, int x);
bool walled(int y, int x);
void fill();
void erose();
void solve();


bool inrange(int y, int x) {
    return y >= 0 && y < H && x >= 0 && x < W;
}

int accwa(int y, int x) {
    if (inrange(y, x)) {
        return wa[y][x];
    }
    return 0;
}

bool walled(int y, int x) {
    return accwa(y, x) >= accwa(y-1, x) && accwa(y, x) >= accwa(y+1, x) && accwa(y, x) >= accwa(y, x-1) && accwa(y, x) >= accwa(y, x+1);
}

void fill() {
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (walled(i, j)) {
                wa[i][j]++;
            }
        }
    }
}

void erose() {
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            int min_neigh = min({accwa(i-1, j), accwa(i+1, j), accwa(i, j-1), accwa(i, j+1)});
            he[i][j] = max(0, he[i][j] - M - min_neigh);
        }
    }
}

void solve() {
    cin >> H >> W >> M;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> he[i][j];
        }
    }

    int num_iterations = 0;
    while (true) {
        fill();
        erose();
        if (accwa(0, 0) == 0) {
            break;
        }
        num_iterations++;
    }

    cout << num_iterations << endl;
}

int main() {
    int T;
    cin >> T;

    for (int t = 1; t <= T; t++) {
        cout << "Case " << t << ": ";
        solve();
    }

    return 0;
}
