#define EPS 1e-9
#define INF 1e9
#define MAXN 105
#define MAXS 1005

using namespace std;

double sq(double x) {
    return x * x;
}

double norm(pair<double, double> p) {
    return sqrt(sq(p.first) + sq(p.second));
}

double abs(double x) {
    return x < 0 ? -x : x;
}

double cross(pair<double, double> a, pair<double, double> b) {
    return a.first * b.second - a.second * b.first;
}

double dot(pair<double, double> a, pair<double, double> b) {
    return a.first * b.first + a.second * b.second;
}

void dijkstra(vector<vector<pair<int, double>>>& adj, vector<double>& dist, vector<bool>& vis) {
    priority_queue<pair<double, int>, vector<pair<double, int>>, greater<pair<double, int>>> pq;
    fill(dist.begin(), dist.end(), INF);
    fill(vis.begin(), vis.end(), false);
    dist[0] = 0;
    pq.push({0, 0});
    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();
        if (vis[u]) continue;
        vis[u] = true;
        for (auto [v, w] : adj[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
}

bool check(double t) {
    vector<vector<pair<int, double>>> adj(N + 2);
    vector<double> dist(N + 2, INF);
    vector<bool> vis(N + 2, false);
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            pair<double, double> dP = {P[j].first - P[i].first, P[j].second - P[i].second};
            pair<double, double> dV = {V[j].first - S * t, V[j].second};
            double d = sq(dot(dV, dV)) - sq(S) * (sq(dP) - sq(t * S));
            if (d < -EPS) return false;
            if (abs(d) < EPS) {
                adj[i].push_back({j, norm(dP) - t * S});
                adj[j].push_back({i, norm(dP) - t * S});
            } else {
                double s = (dot(dP, dV) + sqrt(d)) / (sq(S));
                if (s > -EPS) {
                    adj[i].push_back({j, s});
                    adj[j].push_back({i, s});
                }
            }
        }
        adj[N].push_back({i, abs(P[i]) - t * S});
        adj[i].push_back({N, abs(P[i]) - t * S});
        adj[N + 1].push_back({i, abs(P[i])});
        adj[i].push_back({N + 1, abs(P[i])});
    }
    adj[N].push_back({N + 1, 0});
    dijkstra(adj, dist, vis);
    return dist[N + 1] < INF;
}

double binary_search() {
    double lo = 0, hi = INF;
    for (int i = 0; i < 100; ++i) {
        double mid = (lo + hi) / 2;
        if (check(mid)) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    return (lo + hi) / 2;
}

