    while (T--) {
        input >> str;

        int n = strlen(str);
        int64 num = 0;
        vector<int> q_pos;

        for (int i = 0; i < n; i++) {
            if (str[i] == '1') {
                num |= (1LL << (n - i - 1));
            } else if (str[i] == '?') {
                q_pos.push_back(n - i - 1);
            }
        }

        int num_q = q_pos.size();
        int64 L = 0, R = (1LL << num_q) - 1;

        while (L <= R) {
            int64 mid = (L + R) / 2;
            int64 test_num = num;

            for (int i = 0; i < num_q; i++) {
                if (mid & (1LL << i)) {
                    test_num |= (1LL << q_pos[i]);
                }
            }

            if (test_num * test_num <= num) {
                L = mid + 1;
            } else {
                R = mid - 1;
            }
        }

        int64 result = num;
        for (int i = 0; i < num_q; i++) {
            if (R & (1LL << i)) {
                result |= (1LL << q_pos[i]);
            }
        }

        output << bitset<64>(result).to_string().substr(64 - n) << endl;
    }

    input.close();
    output.close();

