using namespace std;

int dp[600][600];
int M = 100003;

bool poss(int pos, int i, int mark) {
    return (abs(pos-mark) != abs(i-1));
}

int permut(int D) {
    if (D == 0) return 1;
    return (D * permut(D-1)) % M;
}

int cal(int pos, int i, int mark) {
    if (i == 0) return 1;
    if (dp[pos][i] != -1) return dp[pos][i];
    int ans = 0;
    for (int j = 1; j <= pos; j++) {
        if (poss(pos, j, mark)) {
            ans += cal(j, i-1, mark);
            ans %= M;
        }
    }
    return dp[pos][i] = ans;
}

int solve(int mark, int pos) {
    int ans = 0;
    for (int i = 0; i <= pos; i++) {
        ans += cal(pos, i, mark);
        ans %= M;
    }
    return ans;
}

