}

double len(double x, double y) {
    return std::sqrt(x * x + y * y);
}

void angle(double x1, double y1, double x2, double y2, double& cos_alpha, double& sin_alpha) {
    double len1 = len(x1, y1);
    double len2 = len(x2, y2);
    cos_alpha = (x1 * x2 + y1 * y2) / (len1 * len2);
    sin_alpha = (x1 * y2 - x2 * y1) / (len1 * len2);
}

