void gen(int x, VI v) {
    if (x == n) {
        perms.push_back(v);
        return;
    }
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            used[i] = true;
            v.push_back(i);
            gen(x + 1, v);
            v.pop_back();
            used[i] = false;
        }
    }
}

vector<VI> posLeft(VI possible, int query) {
    vector<VI> res;
    for (int i = 0; i < possible.size(); i++) {
        if (possible[i] != query) {
            res.push_back(possible);
            res.back()[i] = query;
        }
    }
    return res;
}

int go(VI possible) {
    if (possible.empty()) return 0;
    if (dp.count(possible)) return dp[possible];

    int &res = dp[possible];
    res = INT_MAX;

    for (int query : possible) {
        for (const VI &pos : perms) {
            vector<VI> next = posLeft(possible, query);
            int steps = max(abs(query - t[possible.size()]), go(next));
            res = min(res, steps);
        }
    }

    return res;
}

void ask(int pos, VI possible) {
    if (vis.count({pos, possible})) return;
    vis.insert({pos, possible});
    if (possible.empty()) {
        result = min(result, pos);
        return;
    }

    for (int query : possible) {
        for (int i = 0; i < possible.size(); i++) {
            if (possible[i] == query) {
                ask(pos + abs(i - t[possible.size()]), posLeft(possible, query));
            }
        }
    }
}

