#include <bits/stdc++.h>
#define ll long long
#define MOD 1000000007
#define Maxn 100007

using namespace std;

ll jie[Maxn], dao[Maxn];
int prim[Maxn], top, flag[Maxn];
int n, m;

ll powMod(ll x, ll y) {
    ll ans = 1;
    while (y) {
        if (y & 1) ans = ans * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return ans;
}

void getJie() {
    jie[0] = jie[1] = dao[0] = dao[1] = 1;
    for (int i = 2; i < Maxn; i++) {
        jie[i] = jie[i - 1] * i % MOD;
        dao[i] = (MOD - MOD / i) * dao[MOD % i] % MOD;
    }
}

ll c(ll x, int y) {
    return jie[x] * dao[y] % MOD * dao[x - y] % MOD;
}

void makePrim() {
    for (int i = 2; i < Maxn; i++) {
        if (!flag[i]) prim[++top] = i;
        for (int j = 1; j <= top && i * prim[j] < Maxn; j++) {
            flag[i * prim[j]] = 1;
            if (i % prim[j] == 0) break;
        }
    }
}

int sign(int x) {
    int ans = 1;
    for (int i = 1; prim[i] * prim[i] <= x; i++) {
        if (x % prim[i] == 0) {
            x /= prim[i];
            int cnt = 1;
            while (x % prim[i] == 0) {
                x /= prim[i];
                cnt++;
            }
            ans = -ans;
            if (cnt & 1) ans = -ans;
        }
    }
    if (x > 1) ans = -ans;
    return ans;
}

