void circular(int n, int a, int b) {
    memset(pd, 0, sizeof(pd));
    int res = 0;
    for (int i = a; i <= b; i++) {
        if (pd[i] || !prime(i)) continue;
        int m = i, digits = log10(i) + 1;
        pd[i] = 1;
        int flag = 1;
        for (int j = 1; j < digits; j++) {
            m = (m % 10) * pow(10, digits - 1) + m / 10;
            if (m > i && m <= b && !pd[m]) {
                if (prime(m)) {
                    res++;
                    pd[m] = 1;
                } else {
                    flag = 0;
                    break;
                }
            }
        }
        if (flag) res++;
    }
    cout << res << endl;
}

