long long gao1() {
    long long ans1 = 0;
    for(int i = 1; i < n; i++) {
        if(m[i] < m[i-1]) {
            ans1 += m[i-1] - m[i];
        }
    }
    return ans1;
}

long long ok(long long x) {
    long long sum = m[0];
    for(int i = 1; i < n; i++) {
        if(m[i] - m[i-1] < x) {
            sum += m[i-1];
        } else {
            sum += m[i];
        }
    }
    return sum;
}

long long gao2() {
    long long low = 0, high = 1e9, ans2 = -1;
    while(low <= high) {
        long long mid = low + (high - low) / 2;
        if(ok(mid) >= ok(mid+1)) {
            ans2 = ok(mid);
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans2;
}

