bool can_do_it(int ratio, int req, int quantity) {
    double lower_bound = req * 0.9 * ratio / 100.0;
    double upper_bound = req * 1.1 * ratio / 100.0;
    return quantity >= lower_bound && quantity <= upper_bound;
}

int solve(std::vector<int>& R, std::vector<std::vector<int>>& Q) {
    int count = 0;
    for (int i = 0; i < Q.size(); i++) {
        std::sort(Q[i].begin(), Q[i].end());
        int min_quantity = Q[i][0];

        bool can_proceed = true;
        for (int j = 1; j < Q[i].size(); j++) {
            if (!can_do_it(R[i], min_quantity, Q[i][j])) {
                can_proceed = false;
                break;
            }
        }

        if (can_proceed) {
            count++;
        }
    }

    return count;
}

