using namespace std;

struct point {
    int x, y;
};

int x[20], y[20], ans[20];

bool cw(const point &a, const point &b, const point &c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x) < 0;
}

vector<point> convexHull(vector<point> p) {
    int n = p.size();
    if (n <= 3) return p;
    sort(p.begin(), p.end(), [](const point &a, const point &b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    vector<point> up, down;
    for (int i = 0; i < n; i++) {
        while (up.size() >= 2 && !cw(up[up.size() - 2], up[up.size() - 1], p[i])) up.pop_back();
        while (down.size() >= 2 && !cw(down[down.size() - 2], down[down.size() - 1], p[i])) down.pop_back();
        up.push_back(p[i]);
        down.push_back(p[i]);
    }
    for (int i = down.size() - 2; i > 0; i--) up.push_back(down[i]);
    return up;
}

bool on_line(point x, point a, point b) {
    return (x.x - a.x) * (b.y - a.y) == (x.y - a.y) * (b.x - a.x);
}

