            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) > 0) {
                    p.push_back({x[j], y[j]});
                }
            }
            vector<point> hull = convexHull(p);
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) == 0) continue;
                for (point h : hull) {
                    if (on_line(h, {x[j], y[j]}, {x[(j + 1) % n]})) {
                        ans[j] = min(ans[j], n - int(hull.size()));
                    }
                }
            }
        }
