const int mod = 1e9 + 7;
const int intmax = 1e9;

int mat[10][10];
int x, r, c, N;

int unhappy() {
    int count = 0;
    FOR(i, r) {
        FOR(j, c) {
            if (mat[i][j] == 1) {
                if (i - 1 >= 0 && mat[i - 1][j] == 1) {
                    count++;
                }
                if (i + 1 < r && mat[i + 1][j] == 1) {
                    count++;
                }
                if (j - 1 >= 0 && mat[i][j - 1] == 1) {
                    count++;
                }
                if (j + 1 < c && mat[i][j + 1] == 1) {
                    count++;
                }
            }
        }
    }
    return count;
}

int rec(int a, int b, int sum) {
    if (a == r) {
        if (sum == N) {
            return unhappy();
        }
        return intmax;
    }
    int ans = intmax;
    mat[a][b] = 0;
    if (b == c - 1) {
        ans = min(ans, rec(a + 1, 0, sum));
    } else {
        ans = min(ans, rec(a, b + 1, sum));
    }
    mat[a][b] = 1;
    if (b == c - 1) {
        ans = min(ans, rec(a + 1, 0, sum + 1));
    } else {
        ans = min(ans, rec(a, b + 1, sum + 1));
    }
    return ans;
}

