using namespace std;

int n, Q;
vector<vector<int>> D, sum;
vector<int> E, S;
vector<vector<bool>> kt;
vector<vector<double>> f;

double res;
int timeht;

int get(int i, int j) {
    return i >= 0 ? sum[j][i] : 0;
}

void dfs(int city, int last) {
    kt[city][last] = true;
    for (int i = 0; i < n; i++) {
        if (!kt[i][city] && D[city][i] < Q) {
            int newTime = timeht + D[city][i] / S[city];
            if (newTime < f[i][last]) {
                f[i][last] = newTime;
                res = min(res, get(last, i) + E[i] + f[i][last]);
                dfs(i, last);
            }
        }
    }
}

void solve(int test) {
    ifstream fin("C.in");
    ofstream fout("C1.out");

    fin >> n >> Q;
    D.resize(n, vector<int>(n));
    sum.resize(n, vector<int>(n, 0));
    E.resize(n);
    S.resize(n);
    kt.resize(n, vector<bool>(n, false));
    f.resize(n, vector<double>(n, 1e18));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            fin >> D[i][j];
            if (j > 0) sum[i][j] = sum[i][j - 1] + D[i][j];
            else sum[i][j] = D[i][j];
        }
    }

    for (int i = 0; i < n; i++) {
        fin >> E[i] >> S[i];
    }

    int start, target;
    fin >> start >> target;

    res = 1e18;
    timeht = 0;
    dfs(start, target);

    fout << "Case #" << test << ": " << res << endl;

    fin.close();
    fout.close();
}

int main() {
    ifstream fin("C.in");
    int numTests;
    fin >> numTests;

    for (int test = 1; test <= numTests; test++) {
        solve(test);
    }

    fin.close();

    return 0;
}
