int gao(int cc, vector<yx>& vv) {
    if (vv.size() == 1) return 0;
    if (re[cc][vv.front().a][vv.front().b] != -1) return re[cc][vv.front().a][vv.front().b];
    int i, j, k, l, x, y, z, ret = 0x3f3f3f3f;
    vector<yx> lft, rgt;
    for (i = 1; i < vv.size(); i++) {
        l = r = 0;
        for (j = 0; j < m; j++) {
            l += da[vv[i].b].cd[j] == '0';
            r += db[vv[i].b].cd[j] == '0';
        }
        if (cc < n - 1) {
            x = gao(cc + 1, lft);
            if (l <= r) y = gao(cc + 1, vv);
            else y = 0x3f3f3f3f;
            z = gao(cc + 1, rgt);
            if (x + y + z < ret) {
                ret = x + y + z;
                tt.a = x;
                tt.b = y;
                tt.c = lft.size();
                tt.d = rgt.size();
            }
        }
        while (i < vv.size() && lft.size() < n + 1) lft.push_back(vv[i++]);
        while (i < vv.size() && rgt.size() < n + 1) rgt.push_back(vv[i++]);
        i--;
    }
    re[cc][vv.front().a][vv.front().b] = ret;
    return ret;
}

