#include <queue>
#include <cmath>

#define MAX 50

char board[MAX][MAX];
bool visited[MAX][MAX];

int clickX, clickY, mineX, mineY;
int testC, caseN=1, R, C, M, usedMines;

struct point {
    int x, y;
    double dist;

    point(int xx, int yy, double d) {
        x = xx;
        y = yy;
        dist = d;
    }

    bool operator<(const point& p) const {
        if (dist == p.dist) {
            return distancesq(y, x, clickY, clickX) > distancesq(p.y, p.x, clickY, clickX);
        }
        return dist < p.dist;
    }
};

double distance(double p1x, double p1y, double p2x, double p2y) {
    return abs(p1x - p2x) + abs(p1y - p2y);
}

double distancesq(double p1x, double p1y, double p2x, double p2y) {
    return pow(p1x - p2x, 2) + pow(p1y - p2y, 2);
}

bool goodPos(int y, int x) {
    return distance(y, x, clickY, clickX) > 1;
}

int main() {
    // Read input from a file
    std::ifstream in("input.txt");
    std::ofstream out("output.txt");

    in >> testC;
    while (testC--) {
        in >> R >> C >> M;

        // Reset variables
        usedMines = 0;
        std::priority_queue<point> pq;

        // Set clicked cell coordinates
        in >> clickY >> clickX;

        // Initialize board and visited arrays
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                board[i][j] = '.';
                visited[i][j] = false;
            }
        }

        // Add clicked cell to priority queue
        pq.push(point(clickX, clickY, 0));

        while (!pq.empty() && usedMines < M) {
            point p = pq.top();
            pq.pop();

            if (visited[p.y][p.x] || board[p.y][p.x] == '*') {
                continue;
            }

            board[p.y][p.x] = '*';
            visited[p.y][p.x] = true;
            usedMines++;

            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    if (goodPos(p.y + i, p.x + j)) {
                        pq.push(point(p.x + j, p.y + i, distance(p.y + i, p.x + j, clickY, clickX)));
                    }
                }
            }
        }

        // Validate board configuration
        bool valid = true;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (board[i][j] == '.') {
                    valid = false;
                    break;
                }
            }
        }

        // Output result
        out << "Case #" << caseN++ << ":" << std::endl;
        if (valid) {
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    out << board[i][j];
                }
                out << std::endl;
            }
        } else {
            out << "Impossible" << std::endl;
        }
    }

    in.close();
    out.close();

    return 0;
}
