int fpow(int base, int exp) {
    int res = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp /= 2;
    }
    return res;
}

int rev(int a) {
    return fpow(a, MOD - 2);
}

int divi(int a, int b) {
    return (a * rev(b)) % MOD;
}

