void go(int x, int p) {
    for(int i = n - 1; i >= 0; i--) {
        if(tab[i][x] == 0) {
            tab[i][x] = p;
            return;
        }
    }
}

void process() {
    vector<vector<int>> ntab(n, vector<int>(n));
    vector<vector<int>> ltab(2 * n - 1, vector<int>(n));

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            ntab[j][i] = tab[i][j];
            ltab[i + j][j] = tab[i][j];
        }
    }

    tab = ntab;

    if(lookfor() || lookfor() || lookfor()) {
        b_w = true;
    }

    tab = ltab;

    if(lookfor() || lookfor() || lookfor()) {
        r_w = true;
    }
}

bool lookfor() {
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(tab[i][j] == 0) continue;

            if(j + k <= n) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(tab[i][j] != tab[i][j + l]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }

            if(i + k <= n) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(tab[i][j] != tab[i + l][j]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }

            if(i + k <= n && j + k <= n) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(tab[i][j] != tab[i + l][j + l]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }

            if(i + k <= n && j - k >= -1) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(tab[i][j] != tab[i + l][j - l]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }
        }
    }

    return false;
}
