int R, C, F;

int findb(vector<vector<char>>& maze, int i, int j, int cost) {
    if (i < 0 || i >= R || j < 0 || j >= C || maze[i][j] == '#') {
        return INT_MAX;
    }

    if (i == R - 1 && j == C - 1) {
        return cost;
    }

    int minCost = INT_MAX;

    if (i + 1 < R) {
        int newCost = (maze[i][j] == '.' && maze[i+1][j] == '.') ? F : 1;
        minCost = min(minCost, findb(maze, i+1, j, cost + newCost));
    }

    minCost = min(minCost, findb(maze, i, j+1, cost + 1));
    minCost = min(minCost, findb(maze, i+1, j+1, cost + 1));
    minCost = min(minCost, findb(maze, i+1, j-1, cost + 1));

    return minCost;
}

