class DisjointSet {
private:
    VI parent;
    int numSets;
public:
    DisjointSet(int n) {
        parent.resize(n);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
        }
        numSets = n;
    }

    int findRoot(int x) {
        return (x == parent[x] ? x : parent[x] = findRoot(parent[x]));
    }

    void unite(int x, int y) {
        x = findRoot(x);
        y = findRoot(y);
        if (x != y) {
            parent[y] = x;
            numSets--;
        }
    }

    int getNumSets() {
        return numSets;
    }
};

