bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int solve(VPII& edges, int n) {
    DisjointSet ds(n);
    for (PII& edge : edges) {
        ds.unite(edge.first, edge.second);
    }
    return ds.getNumSets();
}

