double dis(double x1, double y1, double x2, double y2) {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

double gogo(double angle) {
    if (angle < -1) {
        return -1;
    } else if (angle > 1) {
        return 1;
    } else {
        return angle;
    }
}

void go(double x1, double y1, double x2, double y2, double x3, double y3, int idx) {
    double r1, r2;
    double d1 = dis(x1, y1, x2, y2);
    double d2 = dis(x1, y1, x3, y3);

    if (d1 == 0 && d2 == 0) {
        r1 = r2 = 0;
    } else {
        double angle = acos(gogo(((d1 * d1) + (d2 * d2) - (dis(x2, y2, x3, y3) * dis(x2, y2, x3, y3)) / (2 * d1 * d2)));

        r1 = (PI * d1 * d1 * angle) / (2 * PI);
        r2 = (PI * d2 * d2 * angle) / (2 * PI);
    }

    ret[idx] = (int)round(r1 + r2);
}

