pair<int, int> mymax(pair<int, int> a, pair<int, int> b) {
    if (length(a) > length(b))
        return a;
    else if (length(a) < length(b))
        return b;
    else
        return (a.first < b.first) ? a : b;
}

vector<pair<int, int>> compress(vector<pair<int, int>> segments) {
    sort(segments.begin(), segments.end());
    vector<pair<int, int>> compressed;
    for (auto s : segments) {
        if (compressed.empty() || s.first > compressed.back().second) {
            compressed.push_back(s);
        } else {
            compressed.back().second = max(compressed.back().second, s.second);
        }
    }
    return compressed;
}

pair<int, int> test(vector<pair<int, int>> seg1, vector<pair<int, int>> seg2) {
    vector<pair<int, int>> merged;
    for (auto s1 : seg1) {
        for (auto s2 : seg2) {
            if (s1.first <= s2.second && s2.first <= s1.second) {
                merged.push_back({max(s1.first, s2.first), min(s1.second, s2.second)});
            }
        }
    }
    return *max_element(merged.begin(), merged.end(), [](pair<int, int> a, pair<int, int> b) {
        return length(a) < length(b);
    });
}

