const ull MOD = 1e9 + 7;

ull calc(ull depth, ull prev, ull up, ull bottom) {
    if (depth == size) {
        return (up == 0 && bottom == 0) ? 1 : 0;
    }

    ull &res = memo[depth][prev][up][bottom];
    if (res != -1) {
        return res;
    }

    res = 0;
    for (ull i = 0; i < b; ++i) {
        if (i == b - 1) {
            res = (res + calc(depth + 1, i, (up + prev) % b, (bottom + i) % b)) % MOD;
        } else {
            res = (res + calc(depth + 1, i, (up + prev) % b, bottom)) % MOD;
        }
    }

    return res;
}

