    int res = 0;
    for (int x = 0; x <= curE; x++) {
        res = std::max(res, x * v[pos] + solve(std::min(E, curE - x + R), pos + 1));
    }

    return cache[{curE, pos}] = res;
}

int main(int argc, char* argv[]) {
    int T;
    std::cin >> T;

    for (int t = 0; t < T; t++) {
        std::cin >> E >> R >> N;
        for (int i = 0; i < N; i++) {
            std::cin >> v[i];
        }

        cache.clear();
        int ans = solve(E, 0);
        std::cout << "Case " << t+1 << ": " << ans << std::endl;
    }

    return 0;
}
