bool isok(int r, int c, vector<vector<char>>& grid) {
    return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
}

bool proc(int r, int c, int happy, bool alice, vector<vector<char>>& grid) {
    if (grid[r][c] == 'H') happy = 0;
    if (memo[alice][r][c][happy] != -1) return memo[alice][r][c][happy];
    if (happy == 0) return alice;

    bool win = !isok(r, c, grid);
    for (int dr = -1; dr <= 1; ++dr) {
        for (int dc = -1; dc <= 1; ++dc) {
            if (dr == 0 && dc == 0) continue;
            if ((r + dr + c + dc) % 2 == 0) {
                if (isok(r + dr, c + dc, grid)) {
                    win |= proc(r + dr, c + dc, happy - 1, !alice, grid);
                }
            }
        }
    }

    return memo[alice][r][c][happy] = win;
}

bool canWin(int kr, int kc, int happy, bool alice, vector<vector<char>>& grid) {
    memset(memo, -1, sizeof(memo));
    return proc(kr, kc, happy, alice, grid);
}

