void push(int x, int y) {
    vis[x][y] = 1;
    Q[0][0] = x;
    Q[0][1] = y;
    int front = 0, rear = 1;
    while (front < rear) {
        x = Q[front][0];
        y = Q[front][1];
        for (int i = 0; i < 4; ++i) {
            int nx = x + dir[i][0];
            int ny = y + dir[i][1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && a[nx][ny] != 0 && !vis[nx][ny]) {
                vis[nx][ny] = 1;
                Q[rear][0] = nx;
                Q[rear][1] = ny;
                ++rear;
            }
        }
        ++front;
    }
}
