        }
    }
}

int happy(int k, int b) {
    int next = 0;
    while (k != 1 && k != 4) {
        next = 0;
        while (k > 0) {
            next += pot[k % 10][b];
            k /= 10;
        }
        k = next;
    }
    return (k == 1);
}

